package org.jfree.chart.renderer.category;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Line2D;
import java.awt.Paint;
import java.awt.Stroke;
import java.awt.geom.Line2D;
import java.awt.geom.Rectangle2D;
import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.axis.CategoryAxis;
import org.jfree.chart.axis.ValueAxis;
import org.jfree.chart.entity.EntityCollection;
import org.jfree.chart.event.RendererChangeEvent;
import org.jfree.chart.labels.CategoryItemLabelGenerator;
import org.jfree.chart.plot.CategoryPlot;
import org.jfree.chart.plot.PlotOrientation;
import org.jfree.chart.renderer.category.CategoryItemRendererState;
import org.jfree.chart.util.PaintUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.jfree.chart.util.RectangleEdge;
import org.jfree.chart.util.SerialUtilities;
import org.jfree.data.category.CategoryDataset;
import org.jfree.data.category.StatisticalCategoryDataset;
import org.jfree.data.statistics.StatisticalCategoryDataset;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class StatisticalBarRenderer_drawHorizontalItem_TriageGen1Test {

    private StatisticalBarRenderer renderer;

    @Mock private Graphics2D g2;
    @Mock private CategoryItemRendererState state;
    @Mock private Rectangle2D dataArea;
    @Mock private CategoryPlot plot;
    @Mock private CategoryAxis domainAxis;
    @Mock private ValueAxis rangeAxis;
    @Mock private StatisticalCategoryDataset dataset;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        renderer = spy(new StatisticalBarRenderer());

        // Default mock behaviors to avoid NullPointerException
        when(dataArea.getHeight()).thenReturn(100.0);
        when(dataArea.getWidth()).thenReturn(100.0);
        when(plot.getDomainAxisEdge()).thenReturn(RectangleEdge.BOTTOM);
        when(plot.getRangeAxisEdge()).thenReturn(RectangleEdge.LEFT);
        when(state.getBarWidth()).thenReturn(10.0);

        // Mock dataset defaults
        when(dataset.getMeanValue(anyInt(), anyInt())).thenReturn(10.0);
        when(dataset.getStdDevValue(anyInt(), anyInt())).thenReturn(2.0);

        // Mock axis transformations
        when(domainAxis.getCategoryStart(anyInt(), anyInt(), any(), any())).thenReturn(50.0);
        when(rangeAxis.valueToJava2D(anyDouble(), any(), any())).thenAnswer(inv -> (Double) inv.getArgument(0));

        // Mock renderer methods to prevent deep recursion or NPE
        doReturn(1).when(renderer).getRowCount();
        doReturn(1).when(renderer).getColumnCount();
        doReturn(0.0).when(renderer).getLowerClip();
        doReturn(100.0).when(renderer).getUpperClip();
        doReturn(Color.BLACK).when(renderer).getItemPaint(anyInt(), anyInt());
        doReturn(Color.RED).when(renderer).getItemOutlinePaint(anyInt(), anyInt());
        doReturn(new Color(0,0,0).getStroke()).when(renderer).getItemStroke(anyInt(), anyInt());
        doReturn(new Color(0,0,0).getStroke()).when(renderer).getItemOutlineStroke(anyInt(), anyInt());
        doReturn(null).when(renderer).getItemLabelGenerator(anyInt(), anyInt());
    }

    @Test
    public void testDrawHorizontalItem_SingleSeries_NormalRange() {
        // Case 9-12: lclip=0, uclip=100, value=10
        when(dataset.getMeanValue(0, 0)).thenReturn(10.0);

        renderer.drawHorizontalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
        verify(g2, atLeastOnce()).draw(any(Line2D.class));
    }

    @Test
    public void testDrawHorizontalItem_MultipleSeries_GapCalculation() {
        doReturn(2).when(renderer).getRowCount();
        doReturn(1).when(renderer).getColumnCount();
        // seriesCount > 1 branch

        renderer.drawHorizontalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawHorizontalItem_UclipNegative_ValueTooHigh() {
        // Case 1: uclip <= 0 and value >= uclip
        when(renderer.getUpperClip()).thenReturn(-10.0);
        when(dataset.getMeanValue(0, 0)).thenReturn(5.0);

        renderer.drawHorizontalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2, never()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawHorizontalItem_UclipNegative_ValueVisible() {
        // Case 2: uclip <= 0, value < uclip (e.g., uclip=-10, value=-20)
        when(renderer.getUpperClip()).thenReturn(-10.0);
        when(renderer.getLowerClip()).thenReturn(-50.0);
        when(dataset.getMeanValue(0, 0)).thenReturn(-20.0);

        renderer.drawHorizontalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawHorizontalItem_LclipNegative_ValueHigh() {
        // Case 5-8: lclip <= 0, value >= uclip
        when(renderer.getLowerClip()).thenReturn(-10.0);
        when(renderer.getUpperClip()).thenReturn(50.0);
        when(dataset.getMeanValue(0, 0)).thenReturn(60.0);

        renderer.drawHorizontalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        // value becomes uclip (50), bar should be drawn
        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawHorizontalItem_LclipNegative_ValueLow() {
        // Case 5-8: lclip <= 0, value <= lclip
        when(renderer.getLowerClip()).thenReturn(-10.0);
        when(renderer.getUpperClip()).thenReturn(50.0);
        when(dataset.getMeanValue(0, 0)).thenReturn(-20.0);

        renderer.drawHorizontalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        // value becomes lclip (-10)
        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawHorizontalItem_LclipPositive_ValueTooLow() {
        // Case 9-12: lclip > 0, value <= lclip
        when(renderer.getLowerClip()).thenReturn(10.0);
        when(renderer.getUpperClip()).thenReturn(50.0);
        when(dataset.getMeanValue(0, 0)).thenReturn(5.0);

        renderer.drawHorizontalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2, never()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawHorizontalItem_OutlineAndErrorIndicatorCustom() {
        // Test isDrawBarOutline branch
        doReturn(true).when(renderer).isDrawBarOutline();
        when(state.getBarWidth()).thenReturn(5.0); // > 3

        // Test Error Indicator custom settings
        Stroke customStroke = new Color(0,0,0).getStroke();
        Paint customPaint = Color.BLUE;
        renderer.setErrorIndicatorStroke(customStroke);
        renderer.setErrorIndicatorPaint(customPaint);

        renderer.drawHorizontalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2).setStroke(customStroke);
        verify(g2).setPaint(customPaint);
    }

    @Test
    public void testDrawHorizontalItem_EntityCollection() {
        // Test addItemEntity branch
        org.jfree.chart.entity.EntityCollection entities = mock(org.jfree.chart.entity.EntityCollection.class);
        when(state.getEntityCollection()).thenReturn(entities);

        // We need to spy on the renderer to avoid calling real addItemEntity which might fail
        doNothing().when(renderer).addItemEntity(any(), any(), anyInt(), anyInt(), any());

        renderer.drawHorizontalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(renderer).addItemEntity(eq(entities), eq(dataset), eq(0), eq(0), any(Rectangle2D.class));
    }
}

// Helper class to satisfy compilation if RectangleEdge is internal
enum RectangleEdge { TOP, BOTTOM, LEFT, RIGHT }
